insert into sections (test_id, section_id, "group", title, minutes, instruction, format, config, sort)
select t.id, v.section_id, v.grp, v.title, v.minutes, v.instruction, v.format, v.config, v.sort
from (values
    ('lv1', 'Lesen', 'Lesen, Teil 1', 10, 'Lesen Sie die Aufgaben 1–5 und die Informationen a–h. Welche Information passt zu welcher Situation?', 'matching', '{"bank": [{"key": "A", "text": "Erfolgreich neue Wege gehen: Das Buch „Mit Erfolg durchstarten\" von Dr. Vera Baumgart richtet sich vor allem an Akademikerinnen, die erfolgreich ein eigenes Unternehmen aufbauen wollen. Egal ob Sie sich in der Immobilienbranche, im Bauwesen oder im Gesundheitsbereich selbstständig machen, die Autorin hat Antworten auf alle wichtigen Fragen."}, {"key": "B", "text": "Ein grüner Arbeitsplatz: Die Firma Heller aus Rostock will mit gutem Beispiel vorangehen und behauptet: „Klimafreundliche Energie und Müllvermeidung werden bei uns ganz großgeschrieben\". Aber geht das bei einer Transport- und Logistikfirma überhaupt? Die Antwort ist ein klares „Ja\". Alle Details heute um 19:30 Uhr bei Neo TV."}, {"key": "C", "text": "Verändertes Kaufverhalten: Neuesten Statistiken zufolge greifen Verbraucher in vielen Ländern der Europäischen Union immer mehr zu regionalen und ökologisch angebauten Lebensmitteln. Auch in deutschen Haushalten wird viel Wert auf gesunde Ernährung gelegt. Die Nachfrage nach Bioprodukten ist in den letzten Jahren stetig angestiegen."}, {"key": "D", "text": "Jetzt im Buchhandel: In seinem neuen Bestseller beschreibt Georg Könitz auf eindrucksvolle Weise, wie er von seinem ständig schlecht gelaunten Chef und zwei Mitarbeitern in seinem Team schikaniert, ausgegrenzt und lächerlich gemacht wurde – und wie es ihm schließlich gelang, diesen Teufelskreis zu durchbrechen. Von seinen Erfahrungen können alle, die Ähnliches erleben, profitieren."}, {"key": "E", "text": "Der richtige Praktikumsplatz: Ein Praktikum bietet tolle Möglichkeiten, den Berufsalltag kennenzulernen. Viele Praktikanten sind aber enttäuscht, dass sie nur Hilfsarbeiten verrichten dürfen und dafür schlecht oder gar nicht bezahlt werden. Auf dem Portal dein-praktikum.de findest du jetzt aktuelle Infos und interessante Praktikumsstellen in ganz Deutschland."}, {"key": "F", "text": "Eine Erfolgsgeschichte: Die Bilanz von Rita Jäger (34): Zwei abgebrochene Lehren und zahllose Hilfsjobs. Dann kam Tochter Samantha und Rita musste Verantwortung übernehmen. Im Interview erzählt sie, wie sie in einem Friseursalon die Chance bekam, ein Praktikum und anschließend eine Ausbildung zu machen. Nun hat sie ihren eigenen Salon eröffnet."}, {"key": "G", "text": "Immobilienunternehmen expandiert: Die Frankfurter Immobilienfirma ImmoInvest expandiert nach Süd- und Osteuropa. In den letzten Jahren hat das Unternehmen hohe Gewinne erwirtschaftet und plant nun, außerhalb Deutschlands mehrere Niederlassungen zu gründen. Über die Erfolgsgeschichte des Unternehmens berichtet der Geschäftsführer Herbert Grünberg in unserem Interview."}, {"key": "H", "text": "Neue Broschüre: Sie überlegen, Ihren Lebensmittelpunkt in ein anderes Land zu verlegen? Ein Neuanfang ist eine große Chance, aber immer auch eine Herausforderung – besonders für den Partner oder die Partnerin und die Kinder. Unsere neue Broschüre bietet ausführliche Informationen und Hilfestellungen zum Leben und Arbeiten in der EU."}], "bankTitle": "Informationen", "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 0),
    ('lv2', 'Lesen', 'Lesen, Teil 2', 12, 'Lesen Sie den Text und die Aufgaben 6–9. Entscheiden Sie, welche Lösung richtig ist.', 'mc', '{"passages": [{"paragraphs": [{"t": "Willkommensmappe für neue Mitarbeiterinnen und Mitarbeiter", "b": true}, {"t": "Text 1: Regelungen am Arbeitsplatz", "b": true}, {"t": "Es ist wichtig, dass auf dem Betriebsgelände der AKO.KG alle Maßnahmen eingehalten werden, damit Sie sich selbst und andere nicht gefährden. Bei der Bedienung der Maschinen sind die jeweiligen Sicherheitsbestimmungen zu befolgen, angepasst an die neuen Richtlinien laut Arbeitsschutzgesetz vom Januar dieses Jahres. Die Sicherheitsbestimmungen finden Sie in der Anlage zu dieser Willkommensmappe und zusammengefasst auch auf Informationsblättern an den Maschinen.", "b": false}, {"t": "Sollten Sie hierzu Fragen haben, setzen Sie sich bitte mit unserer Sicherheitsbeauftragten Frau Scholz, Zimmer 122, Durchwahl -308, in Verbindung. Dies ist auch die Kontaktstelle für alle Störungen, Unfälle, Brand oder bei für Sie unklaren Situationen. In diesen Fällen kontaktieren Sie bitte auch immer den Empfang, Durchwahl -100.", "b": false}, {"t": "Nach Verlassen der Werkstätten sind diese immer ordnungsgemäß abzuschließen, damit sich kein Unbefugter den Anlagen und Maschinen nähern kann. Der Arbeitsplatz muss sauber gehalten werden, damit umherliegender Unrat nicht zu einer Gefahrenquelle werden kann. Achten Sie dabei bitte auch auf die vorgeschriebene Trennung der Abfälle in die hierfür vorgesehenen Container im Hof.", "b": false}, {"t": "Auf dem gesamten Betriebsgelände ist Filmen und Fotografieren sowie der Konsum von Alkohol und Zigarettenkonsum nicht gestattet.", "b": false}, {"t": "Text 2: Lebensarbeitszeitkonto", "b": true}, {"t": "In unserem Unternehmen wird die Möglichkeit angeboten, ein Lebensarbeitszeitkonto zu führen. Als Arbeitnehmer können Sie Arbeitszeit, zum Beispiel geleistete Überstunden, als Guthaben auf diesem Konto stehen lassen. Ähnlich wie bei einem Bankkonto, mit dem Unterschied, dass auch die Währung ''Zeit'' akzeptiert wird. Bei Bedarf können Sie Ihre angesparten Stunden wieder einlösen.", "b": false}, {"t": "Das Lebensarbeitszeitkonto bietet die Chance, adäquat auf verschiedene Bedürfnisse zu verschiedenen Zeiten im Laufe des Arbeitslebens einzugehen. Beispielsweise könnte die angesparte Zeit etwa für die Betreuung von pflegebedürftigen Angehörigen genutzt werden.", "b": false}, {"t": "Außerdem bietet unser Teilzeitangebot „Classic Vario\" eine Kombination von Teil- und Vollzeit bei flexibler Einteilung der Arbeitszeit. Nach rechtzeitiger Rücksprache mit dem Arbeitgeber (mindestens drei Monate vorher) kann die zu leistende Arbeitszeit auch zwischen Teil- und Vollzeit angepasst werden.", "b": false}, {"t": "Wenn Sie eine gewisse zeitliche Flexibilität brauchen, können Sie auch kurzfristig nach Absprache im Homeoffice arbeiten. Für die Arbeit von zu Hause stehen den Mitarbeitern und Mitarbeiterinnen ein firmeneigener Laptop und ein Diensthandy zur Verfügung. Sollten Sie eine komplette Auszeit nehmen wollen, können Sie das für einen Zeitraum von bis zu maximal zwölf Monaten vorübergehend tun. Wir sichern Ihnen einen gleichwertigen Arbeitsplatz nach Ihrer Rückkehr zu.", "b": false}]}], "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 1),
    ('lv3', 'Lesen', 'Lesen, Teil 3', 10, 'Lesen Sie die Situationen 10–13 und die Forumsbeiträge a–f. Welcher Beitrag passt zu welcher Situation? Wenn kein Beitrag passt, wählen Sie X.', 'matching', '{"bank": [{"key": "A", "text": "Cécile: Leider muss ich dich enttäuschen. Die Regelung ist gesetzeskonform. Das gesetzliche Minimum liegt sogar nur bei 20 Tagen. Sei froh, dass du mehr hast. Bei manchen Arbeitgebern erhöht sich der Urlaubsanspruch mit längerer Firmenzugehörigkeit."}, {"key": "B", "text": "Limit: Meines Wissens gibt es keine feste gesetzliche Regelung dafür, aber sprich doch einfach mal mit eurem Chef. Dem ist vielleicht gar nicht klar, dass du das nicht so toll findest, wenn du immer erst so kurz vorher weißt, an welchen Tagen du arbeiten musst und wann du frei hast."}, {"key": "C", "text": "Susanne: Urlaub muss immer rechtzeitig beantragt werden, aber der Arbeitgeber ist nicht unbedingt verpflichtet, ihn zu gewähren. Wann Urlaub genommen werden darf, entscheidet der Chef. Aufgrund dringender betrieblicher Gründe kann ein Urlaubsantrag auch abgelehnt werden."}, {"key": "D", "text": "Nico: Schau doch mal in deinen Arbeitsvertrag, da ist das sicher geregelt. Soviel ich weiß, gibt es keine gesetzlichen Einschränkungen für angestellte Arbeitnehmer. Allerdings darfst du keine sieben Tage am Stück arbeiten. Der Samstag gilt in Deutschland als normaler Werktag."}, {"key": "E", "text": "Greta: Ich arbeite auch im Einzelhandel und bei uns ist es so geregelt, dass man einen festen Wochentag freibekommt, wenn man samstags arbeitet. Das kommt mir entgegen. So kann ich entspannt unter der Woche einkaufen oder ins Schwimmbad gehen."}, {"key": "F", "text": "Michele: Das kann dein Chef nicht einfach so machen. Personelle Engpässe reichen für den Widerruf eines bereits genehmigten Urlaubsantrags nicht aus. Wenn du deinen Urlaub tatsächlich verschiebst, muss der Arbeitgeber alle Kosten tragen, die dir durch die Stornierung entstehen."}, {"key": "X", "text": "Kein Beitrag passt."}], "bankTitle": "Forumsbeiträge", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 2),
    ('lv4', 'Lesen', 'Lesen, Teil 4', 13, 'Lesen Sie das Protokoll und die Aufgaben 14–18. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Protokoll 15.04.20XX, 14:00–16:00 Uhr", "b": true}, {"t": "Tagungsraum: 256, Ort: Geschwister-Scholl-Platz 12, 10738 Berlin", "b": false}, {"t": "Anwesende: Petra Kramer (PK, Geschäftsleitung), Yvonne Schmidt (YS, Assistenz der Geschäftsleitung), Thorsten Klein (TK, Leitung Einkauf), Sonja Kühl (SK, Leitung Finanzen), Jenny Mitschke (JM, Leitung Marketing), Ilkay Ergün (IE, Leitung Produktion), Johannes Schön (JS, Leitung Personal)", "b": false}, {"t": "Gast: Jonas Braun (Deutsches Rotes Kreuz)", "b": false}, {"t": "Sitzungsleitung: Johannes Schön. Protokollantin: Yvonne Schmidt.", "b": false}, {"t": "Tagesordnungspunkte:", "b": false}, {"t": "1. Begrüßung und Genehmigung des Protokolls der letzten Sitzung", "b": false}, {"t": "2. Neue Werbemaßnahmen", "b": false}, {"t": "3. Beschwerden über schlecht geputzte Büros", "b": false}, {"t": "4. Fortbildung der Ersthelfer", "b": false}, {"t": "5. Einführung eines Jobtickets", "b": false}, {"t": "6. Sonstiges", "b": false}, {"t": "TOP 1 Begrüßung und Genehmigung des Protokolls der letzten Sitzung: JS begrüßt alle Anwesenden und stellt den Gast Jonas Braun vom Deutschen Roten Kreuz vor. SK merkt an, dass das Datum des diesjährigen Sommerfests falsch im letzten Protokoll festgehalten wurde. Dieses findet am 19.07. statt. Die Änderung wird aufgenommen, ansonsten wird das Protokoll einstimmig genehmigt.", "b": false}, {"t": "TOP 2 Neue Werbemaßnahmen: JM berichtet, dass die Marketingabteilung eine neue Werbestrategie entwickelt hat, um die Verkaufszahlen wieder zu verbessern. SK hatte in der letzten Sitzung berichtet, dass sie seit Januar dieses Jahres stetig zurückgegangen sind. Um langfristige Lösungen zu finden, wurde eine Marktanalyse in Auftrag gegeben. Bevor die Ergebnisse vorliegen, sollen bereits erste Maßnahmen ergriffen werden: Ein IT-Mitarbeiter erarbeitet ein Konzept für eine modernere, suchmaschinenoptimierte Homepage. Zudem schlägt JM kurze, unterhaltsame Werbevideos für soziale Medien vor. PK beauftragt JM, bis zur nächsten Sitzung günstigere Filmteams für die Produktion zu prüfen.", "b": false}, {"t": "TOP 3 Beschwerden über schlecht geputzte Büros: Seit der Zusammenarbeit mit der neuen Reinigungsfirma beschweren sich viele Kollegen über unzureichende Reinigung: schmutzige Tische, volle Mülleimer und ungesaugte Böden. Zudem sind die Reinigungskräfte bei Eintreffen der Mitarbeiter gegen 9 Uhr noch anwesend, obwohl die Arbeiten bis 8:30 Uhr abgeschlossen sein sollten. JS soll Kontakt zur Firma aufnehmen; bei Nichteinhaltung droht die fristlose Kündigung.", "b": false}, {"t": "TOP 4 Fortbildung der Ersthelfer: Für die regelmäßige Fortbildung der Ersthelfer wurde Jonas Braun vom DRK gewonnen. Termin: Samstag, 10.06., Dauer neun Stunden, im Haus, voll als Arbeitszeit angerechnet. Die Teilnehmerzahl ist auf acht Personen beschränkt. Anmeldung bis zum 15.05. in der Personalabteilung.", "b": false}, {"t": "TOP 5 Einführung eines Jobtickets: Zur Verbesserung der Parksituation beteiligt sich die Firma ab dem 01.07. mit 50 Prozent (maximal 60 Euro) an der Monatskarte für öffentliche Verkehrsmittel. Antragsformulare sind bei JS in der Personalabteilung erhältlich.", "b": false}, {"t": "TOP 6 Sonstiges: TK berichtet, dass sich die Lieferzeiten unseres Zulieferers nach Beilegung eines Mitarbeiterstreiks in Litauen wieder normalisiert haben. JS teilt mit, dass ein neu eingestellter Mitarbeiter die Probezeit nicht bestanden hat und die Firma verlassen hat.", "b": false}]}], "maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 3),
    ('lvs1', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 1', 5, 'Lesen Sie die E-Mail und die Aufgaben 19–20. Welche Lösung ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Reklamation: Defekte Spülmaschine und Wasserschaden", "b": true}, {"t": "Sehr geehrte Frau Sturm,", "b": false}, {"t": "vor einer Woche haben wir bei Ihnen eine Spülmaschine für unsere Teeküche gekauft. Sie wurde sehr schnell geliefert und auch gleich eingebaut. Leider muss ich Ihnen heute aber mitteilen, dass sie bereits defekt ist. Beim Spülen ist Wasser ausgelaufen und nun ist unser Parkett beschädigt.", "b": false}, {"t": "Ich bitte Sie, uns umgehend einen Techniker zu schicken, der das Gerät repariert. Wir brauchen die Spülmaschine spätestens übermorgen, da wir ein großes Meeting unserer Außendienstmitarbeiter haben und viele Personen bewirten müssen.", "b": false}, {"t": "Außerdem müssen wir einen Teil des Parketts austauschen. Die Kosten dafür werden wir Ihnen in Rechnung stellen. Bitte schicken Sie mir so schnell wie möglich einen Terminvorschlag für die Reparatur und eine Bestätigung der Kostenübernahme.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Claudio Krüger", "b": false}]}], "maxPoints": 6, "availablePoints": 6, "missing": 0, "pointsPerItem": 3}'::jsonb, 4),
    ('lvs2', 'Lesen und Schreiben', 'Lesen und Schreiben, Teil 2', 15, 'Antworten Sie auf die Beschwerde.', 'writing', '{"passages": [{"paragraphs": [{"t": "Arbeitsanweisung von Ihrer Vorgesetzten:", "b": true}, {"t": "Hallo Frau Retterstein,", "b": false}, {"t": "ich habe gerade die E-Mail von einem großen Kunden bekommen, der sich beschwert hat. Organisieren Sie doch bitte so schnell wie möglich einen Techniker, der sich die Spülmaschine ansieht, und schreiben Sie Herrn Krüger.", "b": false}, {"t": "Entschuldigen Sie sich bitte für die Unannehmlichkeiten und sagen Sie ihm zu, dass wir seine Forderungen in seiner E-Mail prüfen werden.", "b": false}, {"t": "Teilen Sie Herrn Krüger aber bitte vorsorglich mit, dass die Reparatur eventuell nicht sofort durchgeführt werden kann, falls wir Ersatzteile bestellen müssen.", "b": false}, {"t": "Danke und viele Grüße", "b": false}, {"t": "Dorothee Sturm", "b": false}]}], "maxPoints": 7, "availablePoints": 7, "missing": 0, "pointsPerItem": 7}'::jsonb, 5),
    ('hv1', 'Hören', 'Hören, Teil 1', 6, 'Sie hören drei Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben. Entscheiden Sie, ob die Aussage richtig oder falsch ist und welche Antwort am besten passt.', 'mc', '{"maxPoints": 18, "availablePoints": 18, "missing": 0, "pointsPerItem": 3}'::jsonb, 6),
    ('hv2', 'Hören', 'Hören, Teil 2', 5, 'Sie hören vier Aussagen. Welche Aussage a–f passt zu welcher Person 28–31?', 'matching', '{"bank": [{"key": "A", "text": "Arbeitnehmer bekommen zu besonderen Anlässen frei."}, {"key": "B", "text": "Einige Kollegen können nur zu bestimmten Zeiten Urlaub nehmen."}, {"key": "C", "text": "Manchmal müssen Kollegen auch die Aufgaben von anderen übernehmen."}, {"key": "D", "text": "Unter gewissen Umständen gehen Urlaubstage nicht verloren."}, {"key": "E", "text": "Viele Menschen träumen während der Arbeitszeit vom Sommerurlaub."}, {"key": "F", "text": "Wer im Urlaub krank wird, kann Sonderurlaub beantragen."}], "bankTitle": "Aussagen", "maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 7),
    ('hv3', 'Hören', 'Hören, Teil 3', 5, 'Sie hören einen Vortrag über Umweltschutz im Büro. Wählen Sie für die Aufgaben 32–35 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 12, "availablePoints": 12, "missing": 0, "pointsPerItem": 3}'::jsonb, 8),
    ('hv4', 'Hören', 'Hören, Teil 4', 4, 'Sie hören fünf Ansagen auf der Mailbox. Wählen Sie für die Aufgaben 36–40 die richtige Lösung A, B oder C.', 'mc', '{"maxPoints": 15, "availablePoints": 15, "missing": 0, "pointsPerItem": 3}'::jsonb, 9),
    ('hvs', 'Hören und Schreiben', 'Hören und Schreiben, Telefonnotiz', 15, 'Hören Sie die Nachricht und füllen Sie die Telefonnotiz aus.', 'writing', '{"passages": [{"paragraphs": [{"t": "Telefonnotiz: Visitenkarten-Angebot", "b": true}, {"t": "Nachricht auf dem Anrufbeantworter von Herrn Kienzle:", "b": false}, {"t": "„Guten Tag, hier spricht Herr Kienzle, buchstabiert K-I-E-N-Z-L-E. Ich wollte Ihnen bezüglich Ihrer Visitenkartenbestellung ein Angebot unterbreiten. Aktuell haben wir Premiumpapier im Angebot: 100 Stück für 60,99 Euro. Die Lieferung erfolgt innerhalb von zwei Tagen per Expressversand. Bitte rufen Sie mich zurück, um die gewünschte Papiersorte zu bestätigen. Sie erreichen mich unter der Telefonnummer 0179 335 36 37. Vielen Dank und auf Wiederhören.“", "b": false}]}], "maxPoints": 9, "availablePoints": 9, "missing": 0, "pointsPerItem": 9, "audio": "telc-b2-m04-hvs.mp3", "audioPlays": 2}'::jsonb, 10),
    ('sb1', 'Sprachbausteine', 'Sprachbausteine, Teil 1', 10, 'Lesen Sie den Text und schließen Sie die Lücken 46–51. Welches Wort aus der Liste a–j passt in welche Lücke?', 'matching', '{"bank": [{"key": "A", "text": "ANHALTENDE"}, {"key": "B", "text": "AUSDRÜCKLICH"}, {"key": "C", "text": "MÖGLICH"}, {"key": "D", "text": "NÖTIG"}, {"key": "E", "text": "NUR"}, {"key": "F", "text": "SOWIE"}, {"key": "G", "text": "SPÄTERE"}, {"key": "H", "text": "VORZEITIGE"}, {"key": "I", "text": "WEGEN"}, {"key": "J", "text": "ZUM"}], "bankTitle": "Wörterliste", "passages": [{"paragraphs": [{"t": "Kündigung des Arbeitsverhältnisses", "b": true}, {"t": "Sehr geehrter Herr Dr. Reinicke,", "b": false}, {"t": "hiermit kündige ich den mit Ihnen geschlossenen Arbeitsvertrag form- und fristgerecht (46) nächstmöglichen Datum.", "b": false}, {"t": "Wie ich Ihnen in unserem persönlichen Gespräch erklärt habe, habe ich mir die Entscheidung nicht leicht gemacht. Da aber mein Mann von seiner Firma nach Berlin versetzt wurde, wird unsere gesamte Familie so bald wie (47) umziehen.", "b": false}, {"t": "Mir ist bewusst, dass ich eine dreimonatige Kündigungsfrist habe, aber dennoch bitte ich Sie um eine (48) Freistellung ab dem 15. des nächsten Monats.", "b": false}, {"t": "Für die lange Zeit, die ich in dieser Firma hatte, möchte ich mich (49) bei Ihnen bedanken. Ich habe viel in Ihrem Unternehmen gelernt und danke Ihnen für die (50) Unterstützung, die ich stets in der Firma erfahren habe.", "b": false}, {"t": "Bitte bestätigen Sie mir den Erhalt meiner Kündigung (51) das Datum, zu dem der Arbeitsvertrag endet.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Irina Kaspercik", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 11),
    ('sb2', 'Sprachbausteine', 'Sprachbausteine, Teil 2', 10, 'Lesen Sie den Text und schließen Sie die Lücken 52–57. Welche Lösung (A, B oder C) ist jeweils richtig?', 'mc', '{"passages": [{"paragraphs": [{"t": "Angebot für Reinigungsservice", "b": true}, {"t": "Sehr geehrte Damen und Herren,", "b": false}, {"t": "vielen Dank für Ihr Interesse an unseren Leistungen. Für den regelmäßigen Reinigungsservice Ihres Restaurants hatten wir Ihnen am 24.11. ein Angebot (52) unterbreitet. Wie aus der Übersicht auf der zweiten Seite hervorgeht, ist eine Reinigung Ihrer Räumlichkeiten auch am frühen Sonntagmorgen für uns selbstverständlich ohne Probleme machbar. Für diesen Service berechnen wir im Rahmen unserer Rabattaktion keinen Wochenendzuschlag.", "b": false}, {"t": "Hatten Sie schon die Möglichkeit, (53)? Bitte denken Sie daran, dass die erwähnte Rabattaktion nur noch bis Ende des Jahres (54).", "b": false}, {"t": "Sollten Sie dazu noch Fragen haben, zögern Sie bitte nicht, sich mit uns (55). Unsere Mitarbeiter im Kundenservice (56) Ihnen gerne jederzeit zur Verfügung.", "b": false}, {"t": "Wir freuen uns, Sie zukünftig (57) zu können.", "b": false}, {"t": "Mit freundlichen Grüßen", "b": false}, {"t": "Helmuth Heidinger", "b": false}, {"t": "„Tiptop-Service\"", "b": false}]}], "maxPoints": 3, "availablePoints": 3, "missing": 0, "pointsPerItem": 0.5}'::jsonb, 12)
) as v(section_id, grp, title, minutes, instruction, format, config, sort)
join tests t on t.level_id = 'telc-b2' and t.slug = 'modell-04'
on conflict (test_id, section_id) do update set "group" = excluded."group", title = excluded.title, minutes = excluded.minutes, instruction = excluded.instruction, format = excluded.format, config = excluded.config, sort = excluded.sort;

insert into items (section_id, item_id, text, options, points, meta, sort)
select s.id, v.item_id, v.text, v.options, v.points, v.meta, v.sort
from (values
    ('lv1', '1', 'Laura möchte während des Studiums Berufserfahrung sammeln.', null::jsonb, 3, null::jsonb, 0),
    ('lv1', '2', 'Igor hat Familie und möchte im europäischen Ausland arbeiten.', null::jsonb, 3, null::jsonb, 1),
    ('lv1', '3', 'Jens interessiert sich für das Thema Umweltschutz in Unternehmen.', null::jsonb, 3, null::jsonb, 2),
    ('lv1', '4', 'Jasmin hat Probleme mit ihren Kollegen und braucht Hilfe.', null::jsonb, 3, null::jsonb, 3),
    ('lv1', '5', 'Somayeh ist Architektin und möchte ihr eigenes Architekturbüro eröffnen.', null::jsonb, 3, null::jsonb, 4),
    ('lv2', '6', 'Die Regelungen am Arbeitsplatz wurden aktualisiert.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 0),
    ('lv2', '7', 'Auf dem Firmengelände', '[{"key": "A", "text": "darf kein Abfall entsorgt werden."}, {"key": "B", "text": "ist bei Gefahr Frau Scholz zu informieren."}, {"key": "C", "text": "ist es nicht erlaubt, Nahrungsmittel zu sich zu nehmen."}]'::jsonb, 3, null::jsonb, 1),
    ('lv2', '8', 'Das Unternehmen unterstützt die Mitarbeiter finanziell bei privaten Problemen.', '[{"key": "A", "text": "richtig"}, {"key": "B", "text": "falsch"}]'::jsonb, 3, null::jsonb, 2),
    ('lv2', '9', 'Die Mitarbeiter können', '[{"key": "A", "text": "bei Bedarf von zu Hause aus arbeiten."}, {"key": "B", "text": "sich maximal ein halbes Jahr beurlauben lassen."}, {"key": "C", "text": "Geldleistungen für die Pflege von Angehörigen erhalten."}]'::jsonb, 3, null::jsonb, 3),
    ('lv3', '10', 'Thia: Voll gemein, ich habe nur 25 Urlaubstage! Mein Freund hat hingegen 30 Tage im Jahr. Ich frage mich, ob mir nicht auch mehr Tage zustehen. Kennt sich von euch da jemand aus?', null::jsonb, 3, null::jsonb, 0),
    ('lv3', '11', 'Marilena: Ich arbeite im Einzelhandel und bei uns gilt jede Woche ein anderer Dienstplan. Wir bekommen den Plan immer erst am Ende der Vorwoche und deshalb können wir unsere Freizeit natürlich auch nicht richtig planen. Ist das erlaubt?', null::jsonb, 3, null::jsonb, 1),
    ('lv3', '12', 'Hans: Ich habe nach der Genehmigung meines Urlaubs diesen gebucht und jetzt hat mein Chef gemerkt, dass ein anderer Kollege schon vorher zur selben Zeit Urlaub eingereicht hat. Jetzt will er mir meinen wieder streichen. Darf er das?', null::jsonb, 3, null::jsonb, 2),
    ('lv3', '13', 'Lisa: Ich mache zurzeit ein Pflichtpraktikum in einem Unternehmen und arbeite von Montag bis Freitag acht Stunden täglich. Jetzt soll ich nächsten Samstag auch noch kommen. Bin ich dazu verpflichtet? Ich fühle mich ein bisschen ausgenutzt!', null::jsonb, 3, null::jsonb, 3),
    ('lv4', '14', 'Die neue Werbestrategie', '[{"key": "A", "text": "beinhaltet ein Video über die Produktionsabläufe."}, {"key": "B", "text": "ist wegen der schlechten Verkaufszahlen notwendig."}, {"key": "C", "text": "lässt sich sehr schnell und kostengünstig umsetzen."}]'::jsonb, 3, null::jsonb, 0),
    ('lv4', '15', 'Die Reinigungsfirma', '[{"key": "A", "text": "hält sich nicht an die vereinbarten Putzzeiten."}, {"key": "B", "text": "putzt die Büros der Firma nicht regelmäßig."}, {"key": "C", "text": "wird den Vertrag demnächst kündigen."}]'::jsonb, 3, null::jsonb, 1),
    ('lv4', '16', 'Die Fortbildung für Ersthelfer', '[{"key": "A", "text": "ist nur mit begrenzter Teilnehmerzahl möglich."}, {"key": "B", "text": "müssen die Teilnehmer nur einmal absolvieren."}, {"key": "C", "text": "wird beim Deutschen Roten Kreuz veranstaltet."}]'::jsonb, 3, null::jsonb, 2),
    ('lv4', '17', 'Das Jobticket', '[{"key": "A", "text": "soll zu 60 Prozent finanziert werden."}, {"key": "B", "text": "kann in der Personalabteilung beantragt werden."}, {"key": "C", "text": "wird ab nächsten Monat eingeführt."}]'::jsonb, 3, null::jsonb, 3),
